-- ============================================================
-- Pack Hunting: script registration and trainer move
-- ============================================================

-- Freezing Arrow is redundant: woa_2026_08_10_06.sql gives Trap Launcher:
-- Freezing Trap a 40-yard cast from level 20, which is everything Freezing
-- Arrow did at level 80.  Its trap-drop child (60202) and freeze effect (60210)
-- are left in place, simply unreferenced.
--
-- Layout copied from Misdirection 34477, which is the working precedent:
--   Effect1 = SPELL_EFFECT_REDIRECT_THREAT (130), bp 99 + DieSides 1 -> 100%
--   Effect2 = APPLY_AURA / SPELL_AURA_DUMMY on the caster, carrying the duration
-- Registration is entirely generic -- Spell::EffectRedirectThreat
-- (SpellEffects.cpp:5928) calls
--   m_caster->GetThreatMgr().RegisterRedirectThreat(m_spellInfo->Id, unitTarget->GetGUID(), damage)
-- and ThreatManager::AddThreat reads the threat-gaining player's own
-- _redirectInfo (ThreatManager.cpp:424).  Only the teardown needs C++.
--
-- Misdirection targets a raid member (EffectImplicitTargetA1 = 57).  Pack
-- Hunting uses 5 = TARGET_UNIT_PET, the same targeting Mend Pet (136) uses.
--
-- Columns cleared from Freezing Arrow that would otherwise misbehave:
--   Targets            64 -> 0   TARGET_FLAG_DEST_LOCATION; left set, the client
--                                would demand a ground-click reticle.
--   Effect1            32 SPELL_EFFECT_TRIGGER_MISSILE -> 130, and
--   EffectTriggerSpell1 60202 -> 0, EffectRadiusIndex1 7 -> 0,
--   EffectImplicitTargetA1 87 (TARGET_DEST_DEST) -> 5
--   Category           411 / CategoryRecoveryTime 30000 -> 0 / 0, replaced by
--                                RecoveryTime 20000
--   Speed              45.0 -> 0  no longer an arrow
--   AttributesEx2      0x8000000 -> 0
--   SpellFamilyFlags   0x80 -> 0  the trap family bit; Pack Hunting is not a trap
--   EquippedItemClass  2 -> -1    no ranged weapon requirement
DELETE FROM `spell_script_names` WHERE `spell_id` = 60192;
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(60192, 'spell_hun_pack_hunting'),
(60192, 'spell_hun_pack_hunting_aura');

-- TARGET_UNIT_PET with no pet does NOT fail the cast: Spell.cpp:1823 guards with
-- `if (target && target->ToUnit())`, so the redirect effect is silently skipped
-- while Effect2's aura still applies and the 20s cooldown still burns.  The
-- OnCheckCast in spell_hun_pack_hunting is therefore mandatory, not cosmetic.

-- Move the trainer entry from 80 to 24.  The live row was
-- (TrainerId 7, 60192, MoneyCost 100000, ReqLevel 80); 10g is an level-80 price,
-- and its level-24-ish neighbours are 1462 at 7000 and 13161 at 8000, so 5000
-- copper is in band.  npc_trainer is deliberately untouched -- it is legacy and
-- no C++ in src/ reads it (see the note in woa_2026_08_07_00.sql).
UPDATE `trainer_spell` SET `ReqLevel` = 24, `MoneyCost` = 5000 WHERE `SpellId` = 60192;
